import React, { useEffect, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import {
  Input,
  LeaveConfirmModal,
  Select,
  dispatchAppToast,
  useDirtyTracking,
  useLeaveConfirm,
} from '@linm-soft-org/linm-web-common-components';
import { DocumentFormHeader } from '../../../components/layout';
import {
  createPaymentGuarantee,
  getPaymentGuarantee,
  updatePaymentGuarantee,
  type PaymentGuaranteeDetail,
  type PaymentGuaranteeWriteBody,
} from '../../../services/paymentGuarantees/endpoint';
import { useAppDispatch } from '../../../store/hooks';
import df from '../../../styles/documentForm.module.css';

type HeaderForm = {
  maGd: string;
  maPost: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  soLo: string;
  ngayLo: string;
  maKh: string;
  ongBa: string;
  diaChi: string;
  dienGiai: string;
  tkNo: string;
  ngayBl1: string;
  ngayBl2: string;
  ngayXh1: string;
  ngayXh2: string;
  maNt: string;
  tyGia: string;
  lenhRo: string;
  lenhPo: string;
  lenhSo: string;
};

type LineForm = {
  tkCo: string;
  tenTkCo: string;
  maKhC: string;
  tenKhC: string;
  dienGiaiI: string;
  psNt: string;
  maVvI: string;
  maHdI: string;
  maPhiI: string;
  maTtlnI: string;
  maTtcpI: string;
  maBpI: string;
};

const POST_VALUES = ['3', '5', '7', '9'] as const;

function todayLocal(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function emptyHeader(): HeaderForm {
  const today = todayLocal();
  return {
    maGd: '2',
    maPost: '3',
    ngayCt: today,
    ngayLct: today,
    soCt: '',
    soLo: '',
    ngayLo: '',
    maKh: '',
    ongBa: '',
    diaChi: '',
    dienGiai: '',
    tkNo: '',
    ngayBl1: '',
    ngayBl2: '',
    ngayXh1: '',
    ngayXh2: '',
    maNt: '',
    tyGia: '',
    lenhRo: '',
    lenhPo: '',
    lenhSo: '',
  };
}

function emptyLine(): LineForm {
  return {
    tkCo: '',
    tenTkCo: '',
    maKhC: '',
    tenKhC: '',
    dienGiaiI: '',
    psNt: '',
    maVvI: '',
    maHdI: '',
    maPhiI: '',
    maTtlnI: '',
    maTtcpI: '',
    maBpI: '',
  };
}

function dateText(value: string | null | undefined): string {
  if (!value) return '';
  return value.slice(0, 10);
}

function num(value: string): number {
  const text = value.trim();
  if (!text) return 0;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : 0;
}

function round4(value: number): number {
  return Math.round(value * 10000) / 10000;
}

function showMoney(value: number): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value);
}

function blank(value: string): boolean {
  return value.trim() === '';
}

function nullText(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}

function nullNumber(value: string): number | null {
  const text = value.trim();
  if (!text) return null;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function keepPost(value: string): string {
  return POST_VALUES.includes(value as (typeof POST_VALUES)[number]) ? value : '3';
}

function keepGd(value: string): string {
  return value === '3' ? '3' : '2';
}

function headerFromDetail(data: PaymentGuaranteeDetail): HeaderForm {
  return {
    maGd: keepGd(data.maGd),
    maPost: keepPost(data.maPost),
    ngayCt: dateText(data.ngayCt),
    ngayLct: dateText(data.ngayLct),
    soCt: data.soCt ?? '',
    soLo: data.soLo ?? '',
    ngayLo: dateText(data.ngayLo),
    maKh: data.maKh ?? '',
    ongBa: data.ongBa ?? '',
    diaChi: data.diaChi ?? '',
    dienGiai: data.dienGiai ?? '',
    tkNo: data.tkNo ?? '',
    ngayBl1: dateText(data.ngayBl1),
    ngayBl2: dateText(data.ngayBl2),
    ngayXh1: dateText(data.ngayXh1),
    ngayXh2: dateText(data.ngayXh2),
    maNt: data.maNt ?? '',
    tyGia: data.tyGia == null ? '' : String(data.tyGia),
    lenhRo: data.lenhRo ?? '',
    lenhPo: data.lenhPo ?? '',
    lenhSo: data.lenhSo ?? '',
  };
}

function lineFromDetail(line: PaymentGuaranteeDetail['lines'][number]): LineForm {
  return {
    tkCo: line.tkCo ?? '',
    tenTkCo: line.tenTkCo ?? '',
    maKhC: line.maKhC ?? '',
    tenKhC: line.tenKhC ?? '',
    dienGiaiI: line.dienGiaiI ?? '',
    psNt: line.psNt == null ? '' : String(line.psNt),
    maVvI: line.maVvI ?? '',
    maHdI: line.maHdI ?? '',
    maPhiI: line.maPhiI ?? '',
    maTtlnI: line.maTtlnI ?? '',
    maTtcpI: line.maTtcpI ?? '',
    maBpI: line.maBpI ?? '',
  };
}

function toBody(header: HeaderForm, lines: LineForm[]): PaymentGuaranteeWriteBody {
  return {
    maGd: header.maGd === '3' ? '3' : '2',
    maPost: keepPost(header.maPost),
    maCt: 'HBL',
    ngayCt: nullText(header.ngayCt),
    ngayLct: nullText(header.ngayLct),
    soCt: nullText(header.soCt),
    soLo: nullText(header.soLo),
    ngayLo: nullText(header.ngayLo),
    maKh: header.maKh.trim(),
    ongBa: nullText(header.ongBa),
    diaChi: nullText(header.diaChi),
    dienGiai: nullText(header.dienGiai),
    tkNo: nullText(header.tkNo),
    ngayBl1: nullText(header.ngayBl1),
    ngayBl2: nullText(header.ngayBl2),
    ngayXh1: nullText(header.ngayXh1),
    ngayXh2: nullText(header.ngayXh2),
    maNt: nullText(header.maNt),
    tyGia: nullNumber(header.tyGia),
    lenhRo: nullText(header.lenhRo),
    lenhPo: nullText(header.lenhPo),
    lenhSo: nullText(header.lenhSo),
    lines: lines.map(line => ({
      tkCo: line.tkCo.trim(),
      tenTkCo: nullText(line.tenTkCo),
      maKhC: nullText(line.maKhC),
      tenKhC: nullText(line.tenKhC),
      dienGiaiI: nullText(line.dienGiaiI),
      psNt: nullNumber(line.psNt),
      maVvI: nullText(line.maVvI),
      maHdI: nullText(line.maHdI),
      maPhiI: nullText(line.maPhiI),
      maTtlnI: nullText(line.maTtlnI),
      maTtcpI: nullText(line.maTtcpI),
      maBpI: nullText(line.maBpI),
    })),
  };
}

const HblFormPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = searchParams.get('mode') === 'view';
  const isNew = !sttRec;
  const isReadOnly = isView;

  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [header, setHeader] = useState<HeaderForm>(emptyHeader);
  const [lines, setLines] = useState<LineForm[]>([]);
  const [loadError, setLoadError] = useState('');
  const [banner, setBanner] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const source = sttRec || copyFrom;
    if (!source) {
      setHeader(emptyHeader());
      setLines([]);
      setLoadError('');
      markClean();
      return () => { cancelled = true; };
    }
    getPaymentGuarantee(source)
      .then(data => {
        if (cancelled) return;
        setHeader(headerFromDetail(data));
        setLines(data.lines.map(lineFromDetail));
        setLoadError('');
        markClean();
      })
      .catch(() => {
        if (!cancelled) setLoadError('Không tìm thấy hạn mức, bảo lãnh thanh toán');
      });
    return () => { cancelled = true; };
  }, [sttRec, copyFrom]);

  const tPs = round4(lines.reduce((sum, line) => sum + num(line.psNt), 0));
  const title = isView
    ? 'Xem hạn mức, bảo lãnh thanh toán'
    : isNew
      ? 'Thêm hạn mức, bảo lãnh thanh toán'
      : 'Sửa hạn mức, bảo lãnh thanh toán';
  const hideBody = Boolean(loadError);

  const patchHeader = (patch: Partial<HeaderForm>) => {
    markDirty();
    setHeader(prev => ({ ...prev, ...patch }));
  };

  const patchLine = (index: number, patch: Partial<LineForm>) => {
    markDirty();
    setLines(prev => prev.map((line, i) => (i === index ? { ...line, ...patch } : line)));
  };

  const save = async () => {
    if (blank(header.maKh)) {
      setBanner('Bạn chưa nhập mã đối tượng');
      return;
    }
    if (lines.length > 0 && lines.some(line => blank(line.tkCo))) {
      setBanner('Tài khoản chi tiết không được để trống');
      return;
    }
    setBanner('');
    const body = toBody(header, lines);
    setSaving(true);
    try {
      if (sttRec && !isView) await updatePaymentGuarantee(sttRec, body);
      else await createPaymentGuarantee(body);
      markClean();
      dispatchAppToast(dispatch, { message: 'Đã lưu hạn mức, bảo lãnh thanh toán', type: 'success' });
      navigate('/bh/hbl');
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Lưu thất bại',
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={df.page} data-testid="ct-hbl-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={isReadOnly}
        saving={saving}
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        saveTestId="ct-hbl-save-btn"
        onBack={() => guardedNavigate(() => navigate('/bh/hbl'))}
        onSave={hideBody || isReadOnly ? undefined : save}
      />
      {(loadError || banner) ? <div className={df.errorBanner}>{loadError || banner}</div> : null}
      {!hideBody && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Loại giao dịch</label>
                <Select
                  data-testid="ct-hbl-field-maGd"
                  disabled={isReadOnly}
                  value={header.maGd}
                  onChange={e => patchHeader({ maGd: e.target.value })}
                  options={[
                    { value: '2', label: 'Một đối tượng' },
                    { value: '3', label: 'Nhiều đối tượng' },
                  ]}
                />
              </div>
              <div className={df.field}>
                <label className={df.label}>Trạng thái</label>
                <Select
                  data-testid="ct-hbl-field-maPost"
                  disabled={isReadOnly}
                  value={header.maPost}
                  onChange={e => patchHeader({ maPost: e.target.value })}
                  options={[
                    { value: '3', label: 'Hạn mức' },
                    { value: '5', label: 'Bảo lãnh bằng tiền' },
                    { value: '7', label: 'Thế chất tài sản' },
                    { value: '9', label: 'Bảo lãnh ngân hàng' },
                  ]}
                />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày chứng từ</label>
                <Input type="date" data-testid="ct-hbl-field-ngayCt" disabled={isReadOnly} value={header.ngayCt} onChange={e => patchHeader({ ngayCt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày lập chứng từ</label>
                <Input type="date" data-testid="ct-hbl-field-ngayLct" disabled={isReadOnly} value={header.ngayLct} onChange={e => patchHeader({ ngayLct: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số chứng từ</label>
                <Input maxLength={30} data-testid="ct-hbl-field-soCt" disabled={isReadOnly} value={header.soCt} onChange={e => patchHeader({ soCt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lô</label>
                <Input maxLength={30} data-testid="ct-hbl-field-soLo" disabled={isReadOnly} value={header.soLo} onChange={e => patchHeader({ soLo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày lô</label>
                <Input type="date" data-testid="ct-hbl-field-ngayLo" disabled={isReadOnly} value={header.ngayLo} onChange={e => patchHeader({ ngayLo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngoại tệ</label>
                <Input maxLength={3} data-testid="ct-hbl-field-maNt" disabled={isReadOnly} value={header.maNt} onChange={e => patchHeader({ maNt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Tỷ giá</label>
                <Input inputMode="decimal" data-testid="ct-hbl-field-tyGia" disabled={isReadOnly} value={header.tyGia} onChange={e => patchHeader({ tyGia: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Đối tượng</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Đối tượng</label>
                <Input maxLength={30} data-testid="ct-hbl-field-maKh" disabled={isReadOnly} value={header.maKh} onChange={e => patchHeader({ maKh: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Người giao dịch</label>
                <Input maxLength={200} data-testid="ct-hbl-field-ongBa" disabled={isReadOnly} value={header.ongBa} onChange={e => patchHeader({ ongBa: e.target.value })} />
              </div>
              <div className={`${df.field} ${df.spanCol2}`}>
                <label className={df.label}>Địa chỉ</label>
                <Input maxLength={200} data-testid="ct-hbl-field-diaChi" disabled={isReadOnly} value={header.diaChi} onChange={e => patchHeader({ diaChi: e.target.value })} />
              </div>
              <div className={`${df.field} ${df.spanCol2}`}>
                <label className={df.label}>Diễn giải</label>
                <Input maxLength={200} data-testid="ct-hbl-field-dienGiai" disabled={isReadOnly} value={header.dienGiai} onChange={e => patchHeader({ dienGiai: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Tài khoản nợ</label>
                <Input maxLength={30} data-testid="ct-hbl-field-tkNo" disabled={isReadOnly} value={header.tkNo} onChange={e => patchHeader({ tkNo: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Thời hạn và lệnh</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Ngày BL1</label>
                <Input type="date" data-testid="ct-hbl-field-ngayBl1" disabled={isReadOnly} value={header.ngayBl1} onChange={e => patchHeader({ ngayBl1: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày BL2</label>
                <Input type="date" data-testid="ct-hbl-field-ngayBl2" disabled={isReadOnly} value={header.ngayBl2} onChange={e => patchHeader({ ngayBl2: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày XH1</label>
                <Input type="date" data-testid="ct-hbl-field-ngayXh1" disabled={isReadOnly} value={header.ngayXh1} onChange={e => patchHeader({ ngayXh1: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày XH2</label>
                <Input type="date" data-testid="ct-hbl-field-ngayXh2" disabled={isReadOnly} value={header.ngayXh2} onChange={e => patchHeader({ ngayXh2: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lệnh RO</label>
                <Input maxLength={30} data-testid="ct-hbl-field-lenhRo" disabled={isReadOnly} value={header.lenhRo} onChange={e => patchHeader({ lenhRo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lệnh PO</label>
                <Input maxLength={30} data-testid="ct-hbl-field-lenhPo" disabled={isReadOnly} value={header.lenhPo} onChange={e => patchHeader({ lenhPo: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số lệnh</label>
                <Input maxLength={30} data-testid="ct-hbl-field-lenhSo" disabled={isReadOnly} value={header.lenhSo} onChange={e => patchHeader({ lenhSo: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng phiếu</h2>
            {!isReadOnly && (
              <button
                type="button"
                className={df.btnAddLine}
                data-testid="ct-hbl-line-add-btn"
                onClick={() => {
                  markDirty();
                  setLines(prev => [...prev, emptyLine()]);
                }}
              >
                Thêm dòng
              </button>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable}>
                <thead>
                  <tr>
                    <th>Tài khoản có</th>
                    <th>Tên tài khoản</th>
                    <th>Mã đối tượng</th>
                    <th>Tên đối tượng</th>
                    <th>Diễn giải</th>
                    <th>Thành tiền</th>
                    <th>V.Việc</th>
                    <th>Hợp đồng</th>
                    <th>khoản mục</th>
                    <th>Trung tâm lợi nhuận</th>
                    <th>Trung tâm chi phí</th>
                    <th>Phòng ban</th>
                    {!isReadOnly && <th />}
                  </tr>
                </thead>
                <tbody>
                  {lines.map((line, index) => (
                    <tr key={index}>
                      <td>
                        <Input
                          data-testid={`ct-hbl-line-${index}-tkCo`}
                          disabled={isReadOnly}
                          value={line.tkCo}
                          onChange={e => patchLine(index, { tkCo: e.target.value, tenTkCo: '' })}
                        />
                      </td>
                      <td data-testid={`ct-hbl-line-${index}-tenTkCo`}>{line.tenTkCo}</td>
                      <td>
                        <Input
                          data-testid={`ct-hbl-line-${index}-maKhC`}
                          disabled={isReadOnly}
                          value={line.maKhC}
                          onChange={e => patchLine(index, { maKhC: e.target.value, tenKhC: '' })}
                        />
                      </td>
                      <td data-testid={`ct-hbl-line-${index}-tenKhC`}>{line.tenKhC}</td>
                      <td>
                        <Input
                          data-testid={`ct-hbl-line-${index}-dienGiaiI`}
                          disabled={isReadOnly}
                          value={line.dienGiaiI}
                          onChange={e => patchLine(index, { dienGiaiI: e.target.value })}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-hbl-line-${index}-psNt`}
                          disabled={isReadOnly}
                          value={line.psNt}
                          onChange={e => patchLine(index, { psNt: e.target.value })}
                        />
                      </td>
                      <td>
                        <Input data-testid={`ct-hbl-line-${index}-maVvI`} disabled={isReadOnly} value={line.maVvI} onChange={e => patchLine(index, { maVvI: e.target.value })} />
                      </td>
                      <td>
                        <Input data-testid={`ct-hbl-line-${index}-maHdI`} disabled={isReadOnly} value={line.maHdI} onChange={e => patchLine(index, { maHdI: e.target.value })} />
                      </td>
                      <td>
                        <Input data-testid={`ct-hbl-line-${index}-maPhiI`} disabled={isReadOnly} value={line.maPhiI} onChange={e => patchLine(index, { maPhiI: e.target.value })} />
                      </td>
                      <td>
                        <Input data-testid={`ct-hbl-line-${index}-maTtlnI`} disabled={isReadOnly} value={line.maTtlnI} onChange={e => patchLine(index, { maTtlnI: e.target.value })} />
                      </td>
                      <td>
                        <Input data-testid={`ct-hbl-line-${index}-maTtcpI`} disabled={isReadOnly} value={line.maTtcpI} onChange={e => patchLine(index, { maTtcpI: e.target.value })} />
                      </td>
                      <td>
                        <Input data-testid={`ct-hbl-line-${index}-maBpI`} disabled={isReadOnly} value={line.maBpI} onChange={e => patchLine(index, { maBpI: e.target.value })} />
                      </td>
                      {!isReadOnly && (
                        <td>
                          <button
                            type="button"
                            className={df.btnDeleteLine}
                            data-testid={`ct-hbl-line-remove-btn-${index}`}
                            onClick={() => {
                              markDirty();
                              setLines(prev => prev.filter((_, i) => i !== index));
                            }}
                          >
                            ×
                          </button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <div className={df.totalBlock} data-testid="ct-hbl-field-tPs">
              <span className={df.totalLabel}>Tổng tiền</span>
              <span>{showMoney(tPs)}</span>
            </div>
          </div>
        </>
      )}
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default HblFormPage;
